module TwoLinesCover (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] count,\n    input signed [7:0] x[0:7],\n    input signed [7:0] y[0:7],\n    output reg success,\n    output reg done\n);\n    localparam MAX_POINTS = 8;\n    localparam COORD_WIDTH = 8;\n    \n    reg success_temp;\n    reg done_temp;\n    reg [3:0] i, j, k, m;\n    \n    // Cross product terms\n    reg signed [15:0] dx0, dy0;\n    reg signed [15:0] dx1, dy1;\n    reg signed [15:0] prod0, prod1;\n    \n    // Forline check\n    reg [7:0] on_line;\n    reg [7:0] remaining_points;\n    reg [3:0] remaining_count;\n    reg [3:0] rem_idx[0:7];\n    reg rem_collinear;\n    \n    always @(*) begin\n        success_temp = 1'b0;\n        rem_collinear = 1'b0;\n        \n        // Default case: count <= 2\n        if (count <= 4'd2) success_temp = 1'b1;\n        \n        else for (i = 0; i < count; i = i + 1) begin\n            for (j = i+1; j < count; j = j + 1) begin\n                on_line = 8'b0;\n                on_line[i] = 1'b1;\n                on_line[j] = 1'b1;\n                remaining_count = 4'd0;\n                \n                // Check points against line i-j\n                for (k = 0; k < count; k = k + 1) begin\n                    if (k != i && k != j) begin\n                        dx0 = (x[j] - x[i]);\n                        dy0 = (y[j] - y[i]);\n                        dx1 = (x[k] - x[i]);\n                        dy1 = (y[k] - y[i]);\n                        prod0 = dx0 * dy1;\n                        prod1 = dy0 * dx1;\n                        \n                        if (prod0 == prod1) begin\n                            on_line[k] = 1'b1;\n                        end else begin\n                            rem_idx[remaining_count] = k;\n                            remaining_count = remaining_count + 4'd1;\n                        end\n                    end\n                end\n                \n                // Check remaining points collinearity\n                if (remaining_count <= 4'd1) begin\n                    rem_collinear = 1'b1;\n                end else begin\n                    rem_collinear = 1'b1;\n                    // Check if all remaining lie on line defined by first two\n                    for (m = 2; m < remaining_count; m = m + 1) begin\n                        dx0 = (x[rem_idx[1]] - x[rem_idx[0]]);\n                        dy0 = (y[rem_idx[1]] - y[rem_idx[0]]);\n                        dx1 = (x[rem_idx[m]] - x[rem_idx[0]]);\n                        dy1 = (y[rem_idx[m]] - y[rem_idx[0]]);\n                        prod0 = dx0 * dy1;\n                        prod1 = dy0 * dx1;\n                        rem_collinear = rem_collinear && (prod0 == prod1);\n                    end\n                end\n                \n                // If on_line + remaining_collinear\n                if (rem_collinear) success_temp = 1'b1;\n            end\n        end\n    end\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            success <= 1'b0;\n            done <= 1'b0;\n        end\n        else begin\n            done <= start;\n            if (start) success <= success_temp;\n        end\n    end\nendmodule